let particles = [];
let colors = [];
let parNum = 1000; // パーティクルの総数
var mySize;

function setup() {
  mySize = max(windowWidth, windowHeight);
  // pixelDensity(5);
  createCanvas(mySize, mySize);
  colorMode(HSB, 360, 100, 100, 100);
  colors[0] = color(15, 90, 90, random(25, 50));
  colors[1] = color(175, 90, 90, random(25, 50));
  for (let i = 0; i < parNum; i++) {
    particles.push(new Particle(random(width), random(height)));
  } // 全部のパーティクルを作る
  background(0, 0, 5, 100);
}

function draw() {
  // === Variant 2: Organic Lissajous Morph ===
  scalePulse = 1.0 + 0.25 * sin(frameCount * 0.03);
  rotAngle = frameCount * 0.015;
  push();
  translate(width/2, height/2);
  rotate(rotAngle);
  scale(scalePulse);
  translate(-width/2, -height/2);

  for (let j = particles.length - 1; j > 0; j--) {
    particles[j].update();
    particles[j].show();
    if (particles[j].finished()) {
      particles.splice(j, 1);
      background(0, 0, 5, 0.1);
    }
  }

	for (let i = particles.length; i < parNum; i++) {
    particles.push(new Particle(random(width), random(height)));
  } // パーティクルを補充

  pop();
}

